from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema import Data


class SearchProductTool(Component):

    display_name = "Search Product"
    description = (
        "Searches into products catalog to get SKU, name and price in Euro."
    )
    icon = "wallet"
    name = "SearchProductTool"

    inputs = [
        MessageTextInput(
            name="query",
            display_name="User query",
            info="User query for the product, for example 'I need a ThinkPad P16'.",
            tool_mode=True,
        ),
    ]

    outputs = [
        Output(
            display_name="Product info",
            name="output",
            method="search_product",
        ),
    ]

    def search_product(self) -> Data:

        catalog = {
            "LAP-DEV-01": {
                "name": "ThinkPad P16s Gen 2 / MacBook Pro M3",
                "category": "laptop",
                "target_roles": ["Engineering", "Data Science"],
                "price_eur": "1650",
                "specs": "32GB RAM, 1TB SSD, 16-inch display, GPU integrata/dedicata",
                "in_stock": true
            },
            "LAP-STD-02": {
                "name": "Dell Latitude 5540 / MacBook Air M2",
                "category": "laptop",
                "target_roles": ["Marketing", "Sales", "HR", "General"],
                "price_eur": "950",
                "specs": "16GB RAM, 512GB SSD, 15-inch display",
                "in_stock": true
            },
            "MON-4K-01": {
                "name": "Dell UltraSharp 27 4K (U2723QE)",
                "category": "monitor",
                "target_roles": ["All"],
                "price_eur": "520",
                "specs": "27-inch 4K IPS, USB-C Hub 90W power delivery",
                "in_stock": true
            },
            "ACC-DOCK-01": {
                "name": "Thunderbolt 4 Universal Dock",
                "category": "accessory",
                "target_roles": ["All"],
                "price_eur": "190",
                "specs": "Dual 4K output, 100W PD, Gigabit Ethernet",
                "in_stock": true
            }
        }

        query = self.query.strip().lower()

        parole = query.split()
        risultati = []

        for sku, p in catalog.items():
            testo_prodotto = f"{sku} {p['name']} {p['category']}".lower()
            if any(w in testo_prodotto for w in parole):
                risultati.append(p)

        if len(risultati) == 0:
            result = {
                "found": False,
                "error": "Product not found in catalog",
            }
        else:
            result = {
                "found": True,
                "num_found": len(risultati),
                **risultati,

            }

        data = Data(value=result)
        self.status = data

        return data

